
// ================= assets/RabbitSprites: rabbit_rigged.glb -> animated sprite atlases =================
// The SAME GLB is loaded once. For every (fur colour, tooth length, direction) the run cycle is rendered into a small
// atlas that the 2D simulation draws (cheap per frame; depth sorting, hit-testing and the rest of the sim are unchanged).
// Fur colour uses the original recolouring (texture removed, whole material tinted); direction just turns the model.
import * as THREE from "three";
import {GLTFLoader} from "three/addons/loaders/GLTFLoader.js";
// Textures inside a GLB normally reach three.js through blob: URLs, which some viewers/panels block (Content Security Policy).
// Here the embedded images are rewritten to data: URIs and decoded with a plain <img> loader; if a texture still cannot be
// decoded it is replaced by a blank one, so the model always loads and never logs a texture error.
function glbWithDataUris(buf){
  const dv=new DataView(buf); if(dv.getUint32(0,true)!==0x46546C67) return buf;
  const ch=[]; for(let o=12;o<buf.byteLength;){ const len=dv.getUint32(o,true); ch.push({type:dv.getUint32(o+4,true),start:o+8,len}); o+=8+len; }
  const jc=ch.find(c=>c.type===0x4E4F534A), bc=ch.find(c=>c.type===0x004E4942); if(!jc||!bc) return buf;
  const j=JSON.parse(new TextDecoder().decode(new Uint8Array(buf,jc.start,jc.len))); if(!j.images) return buf;
  for(const im of j.images){
    if(im.bufferView==null) continue; const bv=j.bufferViews[im.bufferView];
    const u8=new Uint8Array(buf,bc.start+(bv.byteOffset||0),bv.byteLength); let s=''; for(let i=0;i<u8.length;i+=0x8000) s+=String.fromCharCode.apply(null,u8.subarray(i,i+0x8000));
    im.uri='data:'+(im.mimeType||'image/png')+';base64,'+btoa(s); delete im.bufferView;
  }
  let jb=new TextEncoder().encode(JSON.stringify(j)); const pad=(4-jb.length%4)%4; if(pad){ const t=new Uint8Array(jb.length+pad).fill(0x20); t.set(jb); jb=t; }
  const binLen=bc.len, total=12+8+jb.length+8+binLen, out=new Uint8Array(total), o=new DataView(out.buffer);
  o.setUint32(0,0x46546C67,true); o.setUint32(4,2,true); o.setUint32(8,total,true);
  o.setUint32(12,jb.length,true); o.setUint32(16,0x4E4F534A,true); out.set(jb,20);
  const b0=20+jb.length; o.setUint32(b0,binLen,true); o.setUint32(b0+4,0x004E4942,true); out.set(new Uint8Array(buf,bc.start,binLen),b0+8);
  return out.buffer;
}
function loadGLB(b64){
  const bin=atob(b64), bytes=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
  let data; try{ data=glbWithDataUris(bytes.buffer); }catch(e){ data=bytes.buffer; }
  const loader=new GLTFLoader();
  loader.register(parser=>{
    const tl=new THREE.TextureLoader(parser.options.manager);
    parser.textureLoader={ setCrossOrigin(){return this;}, setRequestHeader(){return this;},
      load(url,ok,prog,bad){ tl.load(url,ok,prog,()=>{ const c=document.createElement('canvas'); c.width=c.height=1; const g=c.getContext('2d'); g.fillStyle='#fff'; g.fillRect(0,0,1,1); const t=new THREE.CanvasTexture(c); ok(t); }); } };
    return {name:'SafeTextures'};
  });
  return new Promise((ok,bad)=>loader.parse(data,'',ok,bad));
}
const GLB_B64="";
const FUR_COLORS={black:0x333333,white:0xffffff};      // black / white recolouring values
const DIRECTIONS={left:-Math.PI/2,right:Math.PI/2};    // model faces +z; turned to run left or right
const TOOTH_LEN={long:2.6,short:0.9};                  // incisor length in model units (exaggerated so it reads at sprite size)
const RS=window.RabbitSprites;
Object.assign(RS,{frames:12,fw:270,fh:180,atlas:{},error:null,bakeMs:0,
  get(fur,teeth,dir){ return this.atlas[fur+'|'+teeth+'|'+dir]||null; }});

function setRabbitColor(rabbit,color){   // same logic as the original page
  rabbit.traverse(o=>{
    if(!o.isMesh||!o.material) return;
    const apply=m=>{ if(!m) return; m.map=null; m.color.set(color); m.needsUpdate=true; };
    Array.isArray(o.material)?o.material.forEach(apply):apply(o.material);
  });
}

// ================= assets/EagleSprites: two bald-eagle poses -> sprite atlases =================
// glide  : "Bald Eagle Flying Bird Model" by Pigcraft (CC BY 4.0) - wings spread, talons tucked, used for the approach.
// strike : "Bald Eagle Catching Fish" by ART & MODELING (CC BY 4.0) - wings raised, talons thrown forward; the fish was removed
//          and the empty talons now hold the rabbit. Used for the last metres of the strike and for carrying the prey away.
// Both GLBs were prepared offline: facing +x, up +y, wingspan along z = 2 units (1 unit ~ 1 m), textures resized.
// Neither model is rigged, so the wingbeat is made here: the wing vertices outside the shoulders are bent up and down
// about the shoulder line, frame by frame, while the body and talons stay still.
const EAGLE_GLIDE_B64="";
const EAGLE_STRIKE_B64="";
const ES=window.EagleSprites;
Object.assign(ES,{frames:16,fw:360,fh:300,atlas:{},grip:{},error:null,get(dir,pose){ return this.atlas[(pose||'glide')+'|'+dir]||null; }});
const EAGLE_POSES={
  glide: {b64:EAGLE_GLIDE_B64, scale:1.00, flap:0.12},                       // soaring: small wing flex
  strike:{b64:EAGLE_STRIKE_B64,scale:1.00, flap:0.40, grip:[0.05,-0.37,0]}   // braking / laden climb: deep wingbeats; grip = talons
};
const EAGLE_YAW=0.45;   // turned this far (rad) towards the viewer so the spread wings read, not just the body edge-on
// One flat, world-space copy of every mesh so the wing bend can be applied to plain float vertex arrays.
function flatEagle(gltf,scale){
  const src=gltf.scene; src.updateMatrixWorld(true); const grp=new THREE.Group(), parts=[]; let ys=0,yn=0;
  src.traverse(o=>{
    if(!o.isMesh) return; const g=o.geometry, P=g.getAttribute('position'), N=g.getAttribute('normal'), n=P.count;
    const nm=new THREE.Matrix3().getNormalMatrix(o.matrixWorld), v=new THREE.Vector3(), p0=new Float32Array(n*3), n0=N?new Float32Array(n*3):null;
    for(let i=0;i<n;i++){
      v.fromBufferAttribute(P,i).applyMatrix4(o.matrixWorld).multiplyScalar(scale); p0[i*3]=v.x; p0[i*3+1]=v.y; p0[i*3+2]=v.z;
      const az=Math.abs(v.z)/scale; if(az>0.10&&az<0.22){ ys+=v.y; yn++; }     // wing roots -> shoulder height
      if(N){ v.fromBufferAttribute(N,i).applyMatrix3(nm).normalize(); n0[i*3]=v.x; n0[i*3+1]=v.y; n0[i*3+2]=v.z; }
    }
    const ng=new THREE.BufferGeometry(); if(g.index) ng.setIndex(g.index);
    ng.setAttribute('position',new THREE.BufferAttribute(p0.slice(),3)); if(N) ng.setAttribute('normal',new THREE.BufferAttribute(n0.slice(),3));
    if(g.getAttribute('uv')) ng.setAttribute('uv',g.getAttribute('uv'));
    const mesh=new THREE.Mesh(ng,o.material); mesh.frustumCulled=false; grp.add(mesh); parts.push({mesh,p0,n0});
  });
  return {grp,parts,scale,py:yn?ys/yn:0};
}
function flapEagle(m,amp,phase){   // bend each wing about its shoulder line; phase 0..1
  const k=m.scale, Z0=0.14*k, ZW=0.20*k, a=Math.sin(phase*Math.PI*2)*amp, py=m.py;
  for(const pt of m.parts){
    const P=pt.mesh.geometry.attributes.position.array, N=pt.n0&&pt.mesh.geometry.attributes.normal.array, p0=pt.p0, n0=pt.n0;
    for(let i=0;i<p0.length;i+=3){
      const x=p0[i], y=p0[i+1], z=p0[i+2], az=Math.abs(z);
      if(az<=Z0||!a){ P[i]=x; P[i+1]=y; P[i+2]=z; if(N){ N[i]=n0[i]; N[i+1]=n0[i+1]; N[i+2]=n0[i+2]; } continue; }
      const sg=z>0?1:-1, t=Math.min(1,(az-Z0)/ZW), w=t*t*(3-2*t), phi=sg*a*(0.55+0.45*w)*w, c=Math.cos(phi), s=Math.sin(phi);
      const dz=z-sg*Z0, dy=y-py;
      P[i]=x; P[i+1]=py+dz*s+dy*c; P[i+2]=sg*Z0+dz*c-dy*s;
      if(N){ const nz=n0[i+2], ny=n0[i+1]; N[i]=n0[i]; N[i+1]=nz*s+ny*c; N[i+2]=nz*c-ny*s; }
    }
    pt.mesh.geometry.attributes.position.needsUpdate=true; if(N) pt.mesh.geometry.attributes.normal.needsUpdate=true;
  }
}
async function bakeEagle(){
  try{
    const {frames,fw,fh}=ES, dirs={right:-EAGLE_YAW,left:Math.PI+EAGLE_YAW}, models={};
    for(const [pose,cfg] of Object.entries(EAGLE_POSES)) models[pose]=flatEagle(await loadGLB(cfg.b64),cfg.scale);
    const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});
    renderer.setPixelRatio(1); renderer.setSize(fw,fh,false); renderer.setClearColor(0x000000,0);
    const scene=new THREE.Scene(), holder=new THREE.Group(); scene.add(holder);
    scene.add(new THREE.HemisphereLight(0xffffff,0x6a5a48,2.6));
    const key=new THREE.DirectionalLight(0xffffff,3.0); key.position.set(-6,8,4); scene.add(key);          // from the upper-left, like the Sun
    const rim=new THREE.DirectionalLight(0xcfe0ff,2.6); rim.position.set(5,4,-7); scene.add(rim);         // cool rim keeps the dark plumage readable on the night sky
    const el=28*Math.PI/180, cam=new THREE.OrthographicCamera(-1,1,1,-1,0.01,3000);
    cam.position.set(0,800*Math.sin(el),800*Math.cos(el)); cam.lookAt(0,0,0); cam.updateMatrixWorld(true);
    const show=pose=>{ holder.clear(); holder.add(models[pose].grp); };
    // one framing shared by both poses (per direction), so swapping glide <-> strike never changes the eagle's size or position
    const bounds={}; let hw=0,hh=0; const v=new THREE.Vector3();
    for(const [d,rot] of Object.entries(dirs)){
      holder.rotation.y=rot; holder.updateMatrixWorld(true); let x0=1e9,x1=-1e9,y0=1e9,y1=-1e9;
      for(const pose of Object.keys(EAGLE_POSES)){ show(pose);
        for(const ph of [0,0.25,0.5,0.75]){ flapEagle(models[pose],EAGLE_POSES[pose].flap,ph);
          for(const pt of models[pose].parts){ const A=pt.mesh.geometry.attributes.position.array;
            for(let i=0;i<A.length;i+=9){ v.set(A[i],A[i+1],A[i+2]).applyMatrix4(holder.matrixWorld).applyMatrix4(cam.matrixWorldInverse); x0=Math.min(x0,v.x);x1=Math.max(x1,v.x);y0=Math.min(y0,v.y);y1=Math.max(y1,v.y); } } } }
      bounds[d]=[(x0+x1)/2,(y0+y1)/2]; hw=Math.max(hw,(x1-x0)/2); hh=Math.max(hh,(y1-y0)/2);
    }
    hw*=1.04; hh*=1.04; if(hw/hh>fw/fh) hh=hw*fh/fw; else hw=hh*fw/fh; ES.uw=2*hw;
    let done=0; const total=Object.keys(dirs).length*Object.keys(EAGLE_POSES).length;
    for(const [d,rot] of Object.entries(dirs)){
      holder.rotation.y=rot; holder.updateMatrixWorld(true); const [cx,cy]=bounds[d];
      cam.left=cx-hw; cam.right=cx+hw; cam.top=cy+hh; cam.bottom=cy-hh; cam.updateProjectionMatrix();
      const gp=EAGLE_POSES.strike.grip; v.set(gp[0],gp[1],gp[2]).multiplyScalar(EAGLE_POSES.strike.scale).applyMatrix4(holder.matrixWorld).applyMatrix4(cam.matrixWorldInverse);
      ES.grip[d]={x:(v.x-cx)/(2*hw),y:-(v.y-cy)/(2*hh)};   // talons, as a fraction of the drawn width / height from the sprite centre (+y down)
      for(const pose of Object.keys(EAGLE_POSES)){
        show(pose); const img=document.createElement('canvas'); img.width=frames*fw; img.height=fh; const g=img.getContext('2d');
        for(let k=0;k<frames;k++){ flapEagle(models[pose],EAGLE_POSES[pose].flap,k/frames); renderer.render(scene,cam); g.drawImage(renderer.domElement,k*fw,0); if(!Boot.active||k%4===3) await new Promise(r=>requestAnimationFrame(r)); }
        ES.atlas[pose+'|'+d]={img,frames,fw,fh}; Boot.set(0.7+0.3*(++done)/total);
      }
    }
    renderer.dispose(); ES.ready=true;
  }catch(e){ ES.error=String(e&&e.message||e); console.warn('GLB eagle unavailable, using a simple stand-in:',e); }
}

(async()=>{
  Boot.started=true; Boot.set(0.05);
  try{
    const t0=performance.now();
    const gltf=await loadGLB(GLB_B64);
    const rabbit=gltf.scene, clip=gltf.animations[0], mixer=new THREE.AnimationMixer(rabbit); mixer.clipAction(clip).play();
    const {frames,fw,fh}=RS;
    const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});
    renderer.setPixelRatio(1); renderer.setSize(fw,fh,false); renderer.setClearColor(0x000000,0);
    const scene=new THREE.Scene(); scene.add(rabbit);
    scene.add(new THREE.HemisphereLight(0xffffff,0x555555,3));
    const key=new THREE.DirectionalLight(0xffffff,3.2); key.position.set(-6,8,4); scene.add(key);   // from the upper-left, like the Sun
    const rim=new THREE.DirectionalLight(0xbfd0ff,1.6); rim.position.set(6,5,-6); scene.add(rim);    // keeps dark fur readable on dark ground
    const setPose=k=>{ mixer.setTime(k/frames*clip.duration); rabbit.updateMatrixWorld(true); };

    // framing per direction: union of the (precise, skinned) bounding boxes over the whole cycle
    const cams={};
    for(const [d,rot] of Object.entries(DIRECTIONS)){
      rabbit.rotation.y=rot; const u=new THREE.Box3();
      for(let k=0;k<frames;k++){ setPose(k); u.union(new THREE.Box3().setFromObject(rabbit,true)); }
      const c=u.getCenter(new THREE.Vector3()), sz=u.getSize(new THREE.Vector3()), hw=sz.x*0.62, hh=hw*fh/fw;
      const cam=new THREE.OrthographicCamera(-hw,hw,hh,-hh,0.01,1000); cam.position.set(c.x,c.y,c.z+50); cam.lookAt(c.x,c.y,c.z);
      cams[d]={cam,ay:fh/2+(c.y-u.min.y)/(2*hh)*fh};          // ay = ground line (px from the top of a frame)
    }

    // incisors: two small boxes attached to the nose bone so they follow the head; length depends on the genotype's tooth trait
    rabbit.rotation.y=DIRECTIONS.left; setPose(0);
    const bone=rabbit.getObjectByName('NoseEnd_M_022');
    const bp=new THREE.Vector3(), bq=new THREE.Quaternion(), bs=new THREE.Vector3(); bone.matrixWorld.decompose(bp,bq,bs);
    const toothMat=new THREE.MeshStandardMaterial({color:0xf1e8c6,roughness:0.5});
    const teeth=[-1,1].map(()=>{ const m=new THREE.Mesh(new THREE.BoxGeometry(1,1,1),toothMat); bone.add(m); return m; });
    const setTeeth=len=>teeth.forEach((m,i)=>{
      const centre=new THREE.Vector3(bp.x+0.8,bp.y-0.35-len/2,bp.z+(i?1:-1)*0.28), off=centre.sub(bp).applyQuaternion(bq.clone().invert()).divide(bs);
      m.position.copy(off); m.quaternion.copy(bq).invert(); m.scale.set(0.55/bs.x,len/bs.y,0.4/bs.z);
    });

    // bake every combination, a few frames per animation frame so the page never stalls
    for(const teethKey of Object.keys(TOOTH_LEN)) for(const fur of Object.keys(FUR_COLORS)) for(const dir of Object.keys(DIRECTIONS)){
      if(fur==='white'&&teethKey==='short') continue;   // this phenotype does not exist in the simulation
      rabbit.rotation.y=DIRECTIONS[dir]; setRabbitColor(rabbit,FUR_COLORS[fur]); setTeeth(TOOTH_LEN[teethKey]);
      const img=document.createElement('canvas'); img.width=frames*fw; img.height=fh; const g=img.getContext('2d');
      for(let k=0;k<frames;k++){
        setPose(k); renderer.render(scene,cams[dir].cam); g.drawImage(renderer.domElement,k*fw,0);
        if(!Boot.active||k%4===3) await new Promise(r=>requestAnimationFrame(r));   // while the start-up gate is up a few frames per tick is fine; afterwards one per displayed frame so the simulation never stalls
      }
      RS.atlas[fur+'|'+teethKey+'|'+dir]={img,frames,fw,fh,ay:cams[dir].ay}; Boot.set(0.05+0.65*Object.keys(RS.atlas).length/6);
    }
    renderer.dispose();
    RS.bakeMs=performance.now()-t0; RS.ready=true;
  }catch(e){ RS.error=String(e&&e.message||e); console.warn('GLB rabbits unavailable, using the drawn rabbits:',e); }
  await bakeEagle();
})();
